  "$schema": "https://opencode.ai/config.json",
  "mcp": {
    "graphql": {
      "type": "local",
      "enabled": true,
      "command": ["bunx", "mcp-graphql"],
      "environment": {
        "ENDPOINT": "http://localhost:13087/graphql"
      }
    }
  },
  "tools": {
    "graphql*": false
  }
}
```


